RESET ROLE;
UPDATE pawpal_private.media_settings SET enabled=true,max_storage_bytes=104857600;
SET LOCAL session_replication_role=replica;
INSERT INTO public.sales_order(id,order_code,customer_id,order_status) VALUES('93000000-0000-0000-0000-000000000001','isolated-review-media','60000000-0000-0000-0000-000000000001','completed');
INSERT INTO public.sales_order_detail(id,order_id,product_variant_id,quantity,unit_price,product_name_snapshot,sku_snapshot) VALUES('93000000-0000-0000-0000-000000000002','93000000-0000-0000-0000-000000000001',gen_random_uuid(),1,100,'Isolated review product','isolated');
SET LOCAL session_replication_role=origin;
SELECT set_config('r.id',gen_random_uuid()::text,true);
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
SET LOCAL ROLE authenticated;
SELECT set_config('r.session',public.prepare_review_media_upload(gen_random_uuid(),current_setting('r.id')::uuid,'93000000-0000-0000-0000-000000000002','sales',100,'image/png','review.png')->>'session_id',true);
SELECT set_config('r.lease',public.claim_media_upload(current_setting('r.session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('r.asset',public.finish_media_upload(current_setting('r.session')::uuid,current_setting('r.lease')::uuid,'10000000-0000-0000-0000-000000000003',repeat('c',64),2,2)::text,true);
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect_error($q$SELECT public.submit_own_sales_reviews('93000000-0000-0000-0000-000000000001',jsonb_build_array(jsonb_build_object('id',current_setting('r.id'),'line_id','93000000-0000-0000-0000-000000000002','rating',5,'content','Isolated review','media_asset_ids',jsonb_build_array(gen_random_uuid()))))$q$,'42501');
RESET ROLE;
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.review WHERE id=current_setting('r.id')::uuid),'wrong media rolls back review');
SET LOCAL ROLE authenticated;
SELECT public.submit_own_sales_reviews('93000000-0000-0000-0000-000000000001',jsonb_build_array(jsonb_build_object('id',current_setting('r.id'),'line_id','93000000-0000-0000-0000-000000000002','rating',5,'content','Isolated review','media_asset_ids',jsonb_build_array(current_setting('r.asset')))));
SELECT public.submit_own_sales_reviews('93000000-0000-0000-0000-000000000001',jsonb_build_array(jsonb_build_object('id',current_setting('r.id'),'line_id','93000000-0000-0000-0000-000000000002','rating',5,'content','Isolated review','media_asset_ids',jsonb_build_array(current_setting('r.asset')))));
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('r.asset')::uuid) IS NOT NULL,'owner reads pending image');
SELECT pg_temp.expect_error($q$SELECT public.prepare_review_media_upload(gen_random_uuid(),current_setting('r.id')::uuid,'93000000-0000-0000-0000-000000000002','sales',100,'image/png','late.png')$q$,'42501');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('r.asset')::uuid) IS NULL,'wrong owner cannot read pending image');
RESET ROLE;
SELECT pg_temp.assert((SELECT count(*)=1 FROM public.review_media WHERE review_id=current_setting('r.id')::uuid),'retry attaches once');
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('r.asset')::uuid) IS NULL,'pending review binary not public');
SELECT pg_temp.assert((SELECT count(*)=0 FROM public.review_media WHERE review_id=current_setting('r.id')::uuid),'pending metadata not public');
RESET ROLE;
UPDATE public.review SET review_status='published' WHERE id=current_setting('r.id')::uuid;
SET LOCAL ROLE anon;
SELECT pg_temp.assert((public.resolve_media_asset(current_setting('r.asset')::uuid)->>'public')::boolean,'published review binary public');
SELECT pg_temp.assert(NOT (public.resolve_media_asset(current_setting('r.asset')::uuid)->>'cache_public')::boolean,'review publication is checked on every download');
SELECT pg_temp.assert((SELECT count(*)=1 FROM public.review_media WHERE review_id=current_setting('r.id')::uuid),'published metadata public');
RESET ROLE;
UPDATE public.review SET review_status='hidden' WHERE id=current_setting('r.id')::uuid;
SET LOCAL ROLE anon;
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('r.asset')::uuid) IS NULL,'hidden review binary revoked');
SELECT pg_temp.assert((SELECT count(*)=0 FROM public.review_media WHERE review_id=current_setting('r.id')::uuid),'hidden metadata revoked');
RESET ROLE;
SET LOCAL session_replication_role=replica;
UPDATE public.appointment SET appointment_status='completed' WHERE id='70000000-0000-0000-0000-000000000001';
